actions.action:
// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate IA state additions
            double additions = 0.0;

            // IA requires addback of:
            // - State income taxes deducted federally
            // - Certain expenses related to exempt income
            // - Interest expense adjustments (IA does not conform to federal §163(j) limitations)

            // Example additions (would be calculated from entity fields):
            // additions += result.state_taxes_deducted;
            // additions += result.exempt_income_expenses;

            apportionment.state_additions = additions;

            // Calculate IA state subtractions
            double subtractions = 0.0;

            // IA allows subtraction of:
            // - Interest on U.S. government obligations (U.S. Treasury bonds, notes, bills)
            //   These are exempt under 31 USC § 3124(a)
            // - Interest on IA state and municipal bonds (exempt for IA purposes)
            // - IA net operating loss deduction (if applicable)
            // - Federal income taxes paid (if applicable to certain entities)

            // Example subtractions (would be calculated from entity fields):
            // subtractions += revenue.federal_bond_interest;
            // subtractions += revenue.ia_municipal_interest;
            // subtractions += result.ia_nol_deduction;

            apportionment.state_subtractions = subtractions;

            // IA uses graduated rates:
            // - 5.5% on first $100,000
            // - 7.1% on amount over $100,000

            result.ia_tax_bracket_1 =
              apportionment.state_tax_bracket_threshold * apportionment.state_tax_rate_bracket_1;

            result.ia_tax_bracket_2 =
              (apportionment.state_taxable_income - apportionment.state_tax_bracket_threshold) *
              apportionment.state_tax_rate_bracket_2;

            apportionment.state_tax = result.ia_tax_bracket_1 + result.ia_tax_bracket_2;

            // Subtract IA state credits
            // IA offers various credits: research activities, high quality jobs,
            // renewable energy, historic preservation, etc.
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // Income is $100,000 or less - apply only bracket 1 rate
            result.ia_tax_bracket_1 =
              apportionment.state_taxable_income * apportionment.state_tax_rate_bracket_1;

            result.ia_tax_bracket_2 = 0.0;

            apportionment.state_tax = result.ia_tax_bracket_1;

            // Subtract IA state credits
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
